import networkx as nx
from networkx.algorithms import clique

def solve_small_n(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    G = nx.Graph()
    for i in range(len(perms)):
        G.add_node(i)

    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            p1 = perms[i]
            p2 = perms[j]
            if all(abs(p1[k] - p2[k]) <= 1 for k in range(n)):
                G.add_edge(i, j)

    # The maximum independent set of G is the maximum clique of the complement graph.
    complement_G = nx.complement(G)
    cliques = clique.find_cliques(complement_G)
    max_size = max(len(c) for c in cliques) if cliques else 0
    return max_size

