def solve_n(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    num_perms = len(perms)
    adj = [0] * num_perms
    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            close = True
            for k in range(n):
                if abs(perms[i][k] - perms[j][k]) > 1:
                    close = False
                    break
            if close:
                adj[i] |= (1 << j)
                adj[j] |= (1 << i)

    for k in range(num_perms, 0, -1):
        for combo in itertools.combinations(range(num_perms), k):
            is_independent = True
            for i in range(len(combo)):
                for j in range(i + 1, len(combo)):
                    if (adj[combo[i]] & (1 << combo[j])):
                        is_independent = False
                        break
                if not is_independent:
