import itertools

def get_components(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    num_perms = len(perms)
    adj = [[] for _ in range(num_perms)]
    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            close = True
            for k in range(n):
                if abs(perms[i][k] - perms[j][k]) > 1:
                    close = False
                    break
            if close:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * num_perms
    components = []
    for i in range(num_perms):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)
    return components

