def solve_max_independent_set_recursive(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    num_perms = len(perms)
    adj = [set() for _ in range(num_perms)]
    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            if is_close(perms[i], perms[j]):
                adj[i].add(j)
                adj[j].add(i)

    best_size = 0

    def backtrack(index, current_set):
        nonlocal best_size
        if index == num_perms:
            best_size = max(best_size, len(current_set))
            return

        if len(current_set) + (num_perms - index) <= best_size:
            return

        # Option 1: Include perms[index]
        can_include = True
        for member_idx in current_set:
            if index in adj[member_idx]:
                can_include = False
                break

        if can_include:
            backtrack(index + 1, current_set + [index])

        # Option 2: Exclude perms[index]
        backtrack(index + 1, current_set)

    # This is still slow for n=5 (120 perms). 
    # Let's use a more efficient approach: Bron-Kerbosch on the complement graph.
    # The complement graph's edges are between permutations that are NOT "close".
    # We want the maximum clique in the complement graph.

    complement_adj = [set() for _ in range(num_perms)]
    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            if not is_close(perms[i], perms[j]):
                complement_adj[i].add(j)
                complement_adj[j].add(i)

    max_clique = 0
    def bron_kerbosch(r, p, x):
        nonlocal max_clique
        if not p and not x:
            max_clique = max(max_clique, len(r))
            return

        if not p:
            return

        # Pruning
        if len(r) + len(p) <= max_clique:
            return

        # Pivot
        u = next(iter(p | x))
        for v in list(p - complement_adj[u]):
            bron_kerbosch(r | {v}, p & complement_adj[v], x & complement_adj[v])
            p.remove(v)
            x.add(v)

    bron_kerbosch(set(), set(range(num_perms)), set())
    return max_clique

