    perms = list(itertools.permutations(range(4)))
    cosets = []
    visited = [False] * 24

    # Map each permutation to its index
    perm_to_idx = {p: i for i, p in enumerate(perms)}

    for p in perms:
        if not visited[perm_to_idx[p]]:
            coset = []
            for v in V4:
                new_p = tuple(p[v[i]] for i in range(4))
                coset.append(new_p)
                visited[perm_to_idx[new_p]] = True
            cosets.append(coset)

    max_size = 0
    # Try all combinations of representatives
    for representatives in itertools.product(*cosets):
        is_independent = True
        for i in range(len(representatives)):
            for j in range(i + 1, len(representatives)):
                if is_close(representatives[i], representatives[j]):
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            max_size = max(max_size, len(representatives))

    print(f"Max independent set size: {max_size}")

solve()
